def merge_lists(lists):
    result = []
    for lst in lists:
        result.extend(lst)
    result.sort()
    return result

void printReverse(int arr[], int n) {
    for (unsigned int i = n - 1; i >= 0; i--) {
        printf("%d ", arr[i]);
    }
}

function dedupeA(arr) {
  return arr.filter((v, i) => arr.indexOf(v) === i);
}
function dedupeB(arr) {
  return [...new Set(arr)];
}
